text:
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": "然後我又是她帶大 "
  } ]
}, {
  "tStartMs": 218468,
  "dDurationMs": 1251,
  "segs": [ {
    "utf8": "她幾乎每兩三天"
  } ]
}, {
  "tStartMs": 219719,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "就會帶我去市場一次"
  } ]
}, {
  "tStartMs": 221821,
  "dDurationMs": 2503,
  "segs": [ {
    "utf8": "所以我那天應該是幾天前吧"
  } ]
}, {
  "tStartMs": 224324,
  "dDurationMs": 1685,
  "segs": [ {
    "utf8": "我在永春市場掃街的時候"
  } ]
}, {
  "tStartMs": 226009,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "因為我以前都在永吉市場"
  } ]
}, {
  "tStartMs": 227410,
  "dDurationMs": 1852,
  "segs": [ {
    "utf8": "然後我們遇到永吉市場的攤販"
  } ]
}, {
  "tStartMs": 229262,
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": "在跟我阿祖說謝謝"
  } ]
}, {
  "tStartMs": 230313,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "說阿祖以前常常到他的攤子買東西"
  } ]
}, {
  "tStartMs": 232715,
  "dDurationMs": 601,
  "segs": [ {
    "utf8": "OK"
  } ]
}, {
  "tStartMs": 233316,
  "dDurationMs": 918,
  "segs": [ {
    "utf8": "所以就是這種"
  } ]
}, {
  "tStartMs": 234234,
  "dDurationMs": 1084,
  "segs": [ {
    "utf8": "我覺得有時候就是"
  } ]
}, {
  "tStartMs": 235318,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "人跟這種土地的這種親近"
  } ]
}, {
  "tStartMs": 237320,
  "dDurationMs": 2803,
  "segs": [ {
    "utf8": "是我小時候很熟悉的感覺"
  } ]
}, {
  "tStartMs": 240123,
  "dDurationMs": 1334,
  "segs": [ {
    "utf8": "我覺得可能是因為這樣子"
  } ]
}, {
  "tStartMs": 241457,
  "dDurationMs": 2620,
  "segs": [ {
    "utf8": "那我們剛剛講到阿宅的一些喜好"
  } ]
}, {
  "tStartMs": 244077,
  "dDurationMs": 1034,
  "segs": [ {
    "utf8": "然後大家也知道說"
  } ]
}, {
  "tStartMs": 245111,
  "dDurationMs": 2536,
  "segs": [ {
    "utf8": "你也非常擅長戰鬥陀螺"
  } ]
}, {
  "tStartMs": 247647,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "然後聽說在家裡是女兒 "
  } ]
}, {
  "tStartMs": 249349,
  "dDurationMs": 767,
  "segs": [ {
    "utf8": "跟你一起玩吧"
  } ]
}, {
  "tStartMs": 250116,
  "dDurationMs": 601,
  "segs": [ {
    "utf8": "對"
  } ]
}, {
  "tStartMs": 250717,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "因為我覺得那個時候是"
  } ]
}, {
  "tStartMs": 252218,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "因為我們幕僚們在玩戰鬥陀螺"
  } ]
}, {
  "tStartMs": 254420,
  "dDurationMs": 1135,
  "segs": [ {
    "utf8": "其實我沒有玩得很好"
  } ]
}, {
  "tStartMs": 255555,
  "dDurationMs": 1568,
  "segs": [ {
    "utf8": "我跟他們玩的時候輸掉"
  } ]
}, {
  "tStartMs": 257123,
  "dDurationMs": 1385,
  "segs": [ {
    "utf8": "輸掉之後我就會不爽 "
  } ]
}, {
  "tStartMs": 258508,
  "dDurationMs": 1635,
  "segs": [ {
    "utf8": "我就跑去買"
  } ]
}, {
  "tStartMs": 260143,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "跑去買的那個過程當中 "
  } ]
}, {
  "tStartMs": 262045,
  "dDurationMs": 1368,
  "segs": [ {
    "utf8": "就認識了那一個"
  } ]
}, {
  "tStartMs": 263413,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "我去南機場買"
  } ]
}, {
  "tStartMs": 264414,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "然後就認識那個老闆"
  } ]
}, {
  "tStartMs": 265915,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "然後我就感受到那種"
  } ]
}, {
  "tStartMs": 267317,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "老闆在地方上的重要性"
  } ]
}, {
  "tStartMs": 269319,
  "dDurationMs": 400,
  "segs": [ {
    "utf8": "OK"
  } ]
}, {
  "tStartMs": 269719,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "因為我就跟老闆說老闆"
  } ]
}, {
  "tStartMs": 271020,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "我這個我需要有人教我"
  } ]
}, {
  "tStartMs": 272422,
  "dDurationMs": 1251,
  "segs": [ {
    "utf8": "你可不可以跟我講一下"
  } ]
}, {
  "tStartMs": 273673,
  "dDurationMs": 1251,
  "segs": [ {
    "utf8": "我要買哪一個比較好"
  } ]
}, {
  "tStartMs": 274924,
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": "那「鋩角」在哪裡"
  } ]
}, {
  "tStartMs": 275975,
  "dDurationMs": 1335,
  "segs": [ {
    "utf8": "結果他就說 這個我知道"
  } ]
}, {
  "tStartMs": 277310,
  "dDurationMs": 2302,
  "segs": [ {
    "utf8": "我們這個書店斜對面有一個廚師"
  } ]
}, {
  "tStartMs": 279612,
  "dDurationMs": 918,
  "segs": [ {
    "utf8": "他今天休假 "
  } ]
}, {
  "tStartMs": 280530,
  "dDurationMs": 1284,
  "segs": [ {
    "utf8": "我叫他來教你 他很厲害"
  } ]
}, {
  "tStartMs": 281814,
  "dDurationMs": 1886,
  "segs": [ {
    "utf8": "他就去提了一個 "
  } ]
}, {
  "tStartMs": 283700,
  "dDurationMs": 951,
  "segs": [ {
    "utf8": "就來教我 "
  } ]
}, {
  "tStartMs": 284651,
  "dDurationMs": 2619,
  "segs": [ {
    "utf8": "我就覺得那種社區的連結就更深了"
  } ]
}, {
  "tStartMs": 287270,
  "dDurationMs": 1685,
  "segs": [ {
    "utf8": "這個就是我們要講的 "
  } ]
}, {
  "tStartMs": 288955,
  "dDurationMs": 1668,
  "segs": [ {
    "utf8": "很多在地的記憶"
  } ]
}, {
  "tStartMs": 290623,
  "dDurationMs": 2586,
  "segs": [ {
    "utf8": "像你剛剛講你是土生土長的台北人"
  } ]
}, {
  "tStartMs": 293209,
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": "我嚴格來說"
  } ]
}, {
  "tStartMs": 294260,
  "dDurationMs": 2453,
  "segs": [ {
    "utf8": " 我其實是宜蘭羅東出身"
  } ]
}, {
  "tStartMs": 296713,
  "dDurationMs": 1801,
  "segs": [ {
    "utf8": "但是我阿公那一代"
  } ]
}, {
  "tStartMs": 298514,
  "dDurationMs": 2353,
  "segs": [ {
    "utf8": "他們就應該是朋友的建議"
  } ]
}, {
  "tStartMs": 300867,
  "dDurationMs": 1451,
  "segs": [ {
    "utf8": " 就帶著我爸爸"
  } ]
}, {
  "tStartMs": 302318,
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "然後我那時候才三歲 "
  } ]
}, {
  "tStartMs": 303803,
  "dDurationMs": 2419,
  "segs": [ {
    "utf8": "就舉家遷往台北"
  } ]
}, {
